import { canonicalSha256 } from '../core/canonical-json.mjs';
function fingerprint(item){return canonicalSha256({severity:item.severity,message:String(item.message).toLowerCase().trim(),spans:item.evidenceSpans??item.anchor??[]});}
export function reflectFindings({deterministicFailures=[],agentFindings=[]}){const final=[...deterministicFailures.map((item)=>({...item,source:'deterministic'}))];const rejected=[];const seen=new Set(final.map(fingerprint));for(const finding of agentFindings){if(!(finding.evidenceSpans?.length||finding.anchor)){rejected.push({...finding,reason:'unsupported: no evidence span or anchor'});continue;}if(!finding.message?.trim()){rejected.push({...finding,reason:'inactionable: missing message'});continue;}const key=fingerprint(finding);if(seen.has(key)){rejected.push({...finding,reason:'duplicate finding'});continue;}seen.add(key);final.push({...finding,source:'agent-reflected'});}const failed=deterministicFailures.some((item)=>['critical','high'].includes(item.severity));const payload={status:failed?'failed':final.length?'passed-with-findings':'passed',final,rejected};return Object.freeze({...payload,reflectionSha256:canonicalSha256(payload)});}
